  local function hexDecode(h)
    local decoded, chunks = {}, 0
    for i = 1, #h, 1024 do
      local part = h:sub(i, i + 1023)
      decoded[#decoded + 1] = part:gsub("%x%x", function(cc) return string.char(tonumber(cc, 16)) end)
      chunks = chunks + 1
      if chunks >= 2 then pull(0); chunks = 0 end
    end
    if chunks > 0 then pull(0) end
    return table.concat(decoded)
  end
