  end

  -- Waits for the next click or key press.
  --   touch -> "touch", x, y
  --   key   -> "key", char, code
  local function waitInput()
    while true do
      local e, _, p1, p2 = pull()
      if e == "touch" then return "touch", p1, p2
      elseif e == "key_down" then return "key", p1, p2 end
    end
  end

  local PALETTE = {
    0x000080, 0x000000, 0x800000, 0x008000, 0x808000, 0x800080,
    0x008080, 0xC0C0C0, 0x0000FF, 0xFF0000, 0x00A000, 0xFFFF00,
    0xFF00FF, 0x00FFFF, 0xFFFFFF, 0x202020,
  }

  local function settingsApp()
    local hit, closeBtn, rsToggle = {}, nil, nil
    local function draw()
      cls()
      bar(1, "Settings - Background Color", GRAY, BLACK)
      hit = {}
      local cols = math.max(4, math.min(8, math.floor((W - 4) / 8)))
      local x0, y0, sw, sh, gap = 3, 3, 6, 3, 2
      for i, c in ipairs(PALETTE) do
        local col = (i - 1) % cols
        local row = math.floor((i - 1) / cols)
        local x, y = x0 + col * (sw + gap), y0 + row * (sh + 1)
        if y + sh <= H - 3 then
          gpu.setBackground(c); gpu.fill(x, y, sw, sh, " ")
          if c == BG then gpu.setForeground((luma(c) > 150) and BLACK or 0xFFFFFF); gpu.set(x + math.floor(sw / 2) - 1, y + 1, "[X]") end
          hit[#hit + 1] = { x, y, x + sw - 1, y + sh - 1, c }
        end
      end
      local rsY = math.max(3, H - 4)
      local rsState = (cfg.rsviewer == "1") and "ON" or "OFF"
      local rsText = "Refined Storage Viewer (R): " .. rsState .. " - click to toggle"
      color(BG, FG); gpu.set(3, rsY, unicode.sub(rsText, 1, math.max(1, W - 4)))
      rsToggle = { 3, rsY, math.max(3, W - 2), rsY }
      gpu.set(3, H - 2, unicode.sub(string.format("Current: #%06X | R toggles RS viewer | Esc closes", BG), 1, math.max(1, W - 4)))
      local cx = W - 9
      color(GRAY, BLACK); gpu.fill(cx, H, 8, 1, " "); gpu.set(cx, H, " Close ")
      closeBtn = { cx, H, cx + 7, H }
      color(BG, FG)
    end
    draw()
    while true do
      local kind, a, b = waitInput()
      if kind == "touch" then
        local x, y = a, b
        if x >= closeBtn[1] and x <= closeBtn[3] and y == closeBtn[4] then break
        elseif rsToggle and x >= rsToggle[1] and x <= rsToggle[3] and y == rsToggle[4] then
          cfg.rsviewer = (cfg.rsviewer == "1") and "0" or "1"; cfgSave(); draw()
        else
          for _, r in ipairs(hit) do
            if x >= r[1] and x <= r[3] and y >= r[2] and y <= r[4] then applyTheme(r[5]); draw(); break end
          end
        end
      elseif kind == "key" then
        if a == 13 or a == 27 or b == 1 then break
        elseif a == 114 or a == 82 then cfg.rsviewer = (cfg.rsviewer == "1") and "0" or "1"; cfgSave(); draw()
        else
          local n = tonumber(unicode.char(a or 0))
          if n == 0 then n = 10 end
          if n and PALETTE[n] then applyTheme(PALETTE[n]); draw() end
        end
      end
    end
    cls()
  end

  local function notepadApp()
    cls()
