  color(BG, RED)
  out("RBMK Console component not found.\n")
  color(BG, FG)
  out("Connect an RBMK console and relaunch the app.\n")
  bar(H, "Press any key to return", GRAY, BLACK)
  waitKey()
  cls()
  return
end
